update country_flag_history set date_start = '1952-10-07', label_fr = 'RSS d''Azerbaïdjan (1952-1991)', label_en = 'Azerbaijan SSR (1952–1991)', notes_fr = 'Dernier drapeau de la RSS : champ rouge traversé d''une bande horizontale bleue, avec la faucille, le marteau et l''étoile dorés. Le tricolore de 1918 le remplace en 1991.', notes_en = 'The SSR''s last flag: a red field crossed by a horizontal blue band, with a golden hammer, sickle and star. The 1918 tricolour replaced it in 1991.', image_url = '/flags/history/az-1952.svg' where id = 1486 and iso_code = 'az';
